import {Rack,encodeStereoWav} from './rack.mjs';
self.onmessage=({data:d})=>{try{let chunks,rate=d.rate||44100;if(d.type==='recording')chunks=d.chunks;else{const r=new Rack(rate,d.set),body=Math.round(rate*64*60/d.set.bpm/4),tail=rate*4,total=body+tail,pcm=new Float32Array(total*2);r.start();for(let i=0;i<total;i++){if(i===body)r.stop();const x=r.sample();if(r.error)throw Error(r.error);const fade=Math.min(1,(total-i)/(rate*.2));pcm[i*2]=x[0]*fade;pcm[i*2+1]=x[1]*fade;}chunks=[pcm];}const buffer=encodeStereoWav(chunks,rate);self.postMessage({buffer},[buffer]);}catch(e){self.postMessage({error:e.message});}};
